//
// This is only a SKELETON file for the 'Word Search' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const DIRECTIONS = [
  [0, 1], // right
  [1, 0], // down
  [1, 1], // down-right
  [1, -1], // down-left
  [0, -1], // left
  [-1, 0], // up
  [-1, 1], // up-right
  [-1, -1], // up-left
];

class WordSearch {
  constructor(grid) {
    this.grid = grid;
  }

  find(words) {
    const results = {};
    for (const word of words) {
      results[word] = this.locate(word);
    }
    return results;
  }

  locate(word) {
    const rows = this.grid.length;
    const cols = this.grid[0].length;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        for (const [dRow, dCol] of DIRECTIONS) {
          if (this.matches(word, row, col, dRow, dCol)) {
            return {
              start: [row + 1, col + 1],
              end: [
                row + 1 + dRow * (word.length - 1),
                col + 1 + dCol * (word.length - 1),
              ],
            };
          }
        }
      }
    }

    return undefined;
  }

  matches(word, row, col, dRow, dCol) {
    for (let i = 0; i < word.length; i++) {
      const r = row + dRow * i;
      const c = col + dCol * i;
      if (
        r < 0 ||
        r >= this.grid.length ||
        c < 0 ||
        c >= this.grid[0].length ||
        this.grid[r][c] !== word[i]
      ) {
        return false;
      }
    }
    return true;
  }
}

export default WordSearch;

